// Original, lesson-specific practice. Never substitute a general subject bank
// when a learner has chosen a narrow lesson. The online service supplies fresh
// sets once these have been seen, and for lessons without a built-in set.
import { getQuizChapter, getQuizConceptId, getQuizLesson, getLessonQuizId } from './quizLessons.js';
import { BROAD_LESSON_BANK } from './quizBroadLessonQuestions.js';

const q = (kind, difficulty, prompt, answer, distractors, explanation) => ({
  kind, difficulty, q: prompt, answer, options: [answer, ...distractors], explanation, source: 'local',
});
const E = 'Easy', M = 'Medium', H = 'Hard';
const bank = {
  'science-mathematics--forces': [
    q('Concept', E, 'A book rests on a level table. What is the net force on it?', 'Zero: the upward support balances its weight', ['Its weight only', 'The upward support only', 'A constant downward net force'], 'Rest means no acceleration in this situation. Gravity still acts, but the table supplies an equal upward normal force; balanced forces do not mean no forces.'),
    q('Mechanism', E, 'What does inertia describe?', 'Resistance to a change in velocity', ['A force that keeps every moving object speeding up', 'The tendency of all objects to move upward', 'A stored supply of acceleration'], 'An object maintains its velocity unless a net external force changes it. Mass measures inertia: more mass requires more net force for the same acceleration.'),
    q('Scenario', E, 'A puck moves across an ideal frictionless horizontal surface. After the push ends, what happens?', 'It continues at constant velocity if no net horizontal force acts', ['It must gradually stop', 'It accelerates forever', 'Its mass decreases'], 'Motion does not require a continuing net force. A net force is needed to change velocity; everyday objects slow because friction or drag supplies that force.'),
    q('Calculation', M, 'A net force of 12 N acts on a 3 kg object. What is its acceleration?', '4 m/s²', ['36 m/s²', '0.25 m/s²', '9 m/s²'], 'Newton’s second law gives a = Fnet / m = 12 / 3 = 4 m/s². Use the net force, after combining forces with their directions, rather than any one force.'),
    q('Comparison', M, 'Two carts experience the same net force. One has twice the mass. How do their accelerations compare?', 'The heavier cart has half the acceleration', ['The heavier cart has twice the acceleration', 'Their accelerations must be equal', 'The heavier cart cannot accelerate'], 'For a fixed net force, acceleration is inversely proportional to mass. Doubling mass divides Fnet / m by two; it does not change the direction set by the net force.'),
    q('Misconception', M, 'Why do action–reaction forces not cancel the acceleration of a single cart?', 'The equal and opposite forces act on different objects', ['One force is always delayed', 'The heavier object has no reaction force', 'Newton’s third law applies only at rest'], 'A free-body diagram contains forces acting on one object. A third-law pair belongs to two different objects, so the pair is not added as two forces on that one cart.'),
    q('Multi-step', H, 'A 5 kg crate is pulled horizontally with 25 N while friction opposes motion with 10 N. What is its acceleration?', '3 m/s² in the pulling direction', ['5 m/s² in the pulling direction', '7 m/s² in the pulling direction', '2 m/s² opposite the pull'], 'First combine the horizontal forces: 25 − 10 = 15 N. Then a = 15 / 5 = 3 m/s². Dividing the pull alone by mass would ignore friction.'),
    q('Transfer', H, 'A car travels around a level circular track at constant speed. Why is it accelerating?', 'Its velocity changes direction, requiring a net inward force', ['Constant speed means the net force is zero', 'Its mass increases continuously', 'A net outward force makes it turn inward'], 'Velocity includes direction as well as speed. Circular motion changes direction continuously, so centripetal acceleration points inward even when the speedometer reading is constant.'),
  ],
  'science-mathematics--energy': [
    q('Concept', E, 'What happens to energy when friction slows a sliding block?', 'Much of its organized kinetic energy becomes internal energy', ['Energy is destroyed', 'All energy becomes mass', 'The block loses gravity'], 'Friction transfers energy into microscopic motion and deformation in the surfaces and surroundings. The block’s kinetic energy decreases, but total energy remains conserved.'),
    q('Comparison', E, 'Which object has kinetic energy relative to the ground?', 'A moving bicycle', ['Only an unplugged lamp at rest', 'Only a stationary spring with no deformation', 'Only a label describing a battery'], 'Kinetic energy is energy associated with motion in a chosen reference frame. A moving bicycle has it even if its speed and direction are currently constant.'),
    q('Mechanism', E, 'Why does lifting a book increase its gravitational potential energy near Earth?', 'Work transfers energy to the book–Earth system as separation increases', ['Gravity disappears above a table', 'The book gains electric charge', 'Potential energy requires the book to keep moving'], 'Lifting against gravity transfers energy to the interacting system. The energy can remain stored after the book stops and can be transferred again if it falls.'),
    q('Calculation', M, 'A 2 kg object moves at 3 m/s. What is its kinetic energy?', '9 J', ['6 J', '18 J', '3 J'], 'Use K = ½mv²: ½ × 2 × 3² = 9 joules. Squaring the speed before multiplying is essential; kinetic energy is not simply mass times speed.'),
    q('Calculation', M, 'A constant 10 N force acts along a 2 m displacement. How much work does it do?', '20 J', ['5 J', '12 J', '0.2 J'], 'For a force parallel to displacement, W = Fd = 10 × 2 = 20 J. If force and motion are not parallel, only the force component along displacement contributes.'),
    q('Scenario', M, 'An ideal pendulum moves from its highest point toward its lowest. What energy change occurs?', 'Gravitational potential energy decreases while kinetic energy increases', ['Both energies must decrease to zero', 'Kinetic energy turns entirely into mass', 'Gravity creates new total energy'], 'In an ideal pendulum without dissipative losses, total mechanical energy is constant. As height decreases, gravitational potential energy transfers into kinetic energy.'),
    q('Scaling', H, 'A car’s speed doubles while its mass stays constant. How does its kinetic energy change?', 'It becomes four times as large', ['It doubles', 'It halves', 'It stays constant'], 'Kinetic energy is proportional to speed squared. Replacing v with 2v multiplies ½mv² by four, which helps explain why stopping demands grow sharply with speed.'),
    q('Multi-step', H, 'A 100 J energy input produces 35 J of useful output. Where is the rest in a real device?', '65 J is transferred in other forms, such as heat and sound', ['65 J is destroyed', 'The device has 350% efficiency', 'Only 35 J entered the device'], 'Useful efficiency is 35 / 100 = 35%. Conservation accounts for all 100 J, but only 35 J serves the intended purpose; the remaining 65 J goes to other outputs or storage.'),
  ],
  'science-mathematics--circuits': [
    q('Concept', E, 'What does electric current measure?', 'The rate of flow of electric charge', ['The total resistance of a wire', 'The energy of one battery only', 'The physical speed of a light bulb'], 'Current is charge passing a point per unit time, measured in amperes. Voltage instead describes energy transferred per unit charge between two points.'),
    q('Mechanism', E, 'Why does a simple battery–bulb circuit need a closed conducting path?', 'Charge needs a continuous path through the circuit', ['The battery must destroy electrons', 'The bulb supplies unlimited charge', 'An open switch increases every current'], 'An open switch interrupts the conducting path, so a steady current cannot flow through the bulb. The battery transfers energy; it does not continuously create and consume electrons.'),
    q('Comparison', E, 'In an ideal single-loop series circuit, how does steady current compare at different points?', 'It is the same throughout the loop', ['It is used up after each resistor', 'It is largest only inside the battery', 'It becomes negative after every bulb'], 'Charge does not build up indefinitely at a point in a steady series circuit. The same amount of charge per second passes each component, though energy per charge changes.'),
    q('Calculation', M, 'A 12 V supply is connected across a 4 Ω ideal resistor. What is the current?', '3 A', ['48 A', '0.33 A', '8 A'], 'Ohm’s law gives I = V / R = 12 / 4 = 3 A for this ohmic resistor. Voltage is measured across the resistor; current flows through it.'),
    q('Comparison', M, 'Two 3 Ω resistors are placed in series. What is their equivalent resistance?', '6 Ω', ['1.5 Ω', '3 Ω', '9 Ω'], 'Series resistances add because the same current must pass through both, and their voltage drops add: Req = 3 + 3 = 6 Ω.'),
    q('Scenario', M, 'One branch of two parallel bulbs opens while an ideal supply remains connected. What happens to the intact branch?', 'It can still conduct through its own complete path', ['Its path must also become open', 'Its resistance becomes zero automatically', 'All charge disappears'], 'Parallel branches connect across the same pair of supply nodes. An interruption in one branch does not by itself break the other branch’s complete path.'),
    q('Multi-step', H, 'Two 6 Ω resistors are in parallel across 12 V. What total current comes from the ideal source?', '4 A', ['1 A', '2 A', '12 A'], 'Each branch draws 12 / 6 = 2 A. The source supplies their sum, 4 A. Equivalently, the parallel combination is 3 Ω and I = 12 / 3.'),
    q('Scaling', H, 'Across a fixed ideal resistor, the voltage doubles. What happens to electrical power?', 'It quadruples', ['It doubles', 'It halves', 'It stays constant'], 'For a fixed resistance, P = V² / R. Doubling V gives four times the power. This conclusion assumes the resistance stays constant rather than changing with temperature.'),
  ],
  'science-mathematics--atoms': [
    q('Concept', E, 'Which particle count defines the chemical element?', 'The number of protons in the nucleus', ['The number of neutrons only', 'The number of electron shells only', 'The total number of particles in a sample'], 'Atomic number is the proton count. Changing neutrons makes an isotope of the same element; changing electrons makes an ion without changing the element.'),
    q('Comparison', E, 'How do two isotopes of the same element differ?', 'They have different neutron counts', ['They must have different proton counts', 'One contains no nucleus', 'They must have opposite electric charges'], 'Isotopes share a proton count but differ in neutrons and therefore mass number. Isotope identity and ion charge describe separate properties.'),
    q('Mechanism', E, 'A neutral atom loses one electron without changing its nucleus. What does it become?', 'A positively charged ion of the same element', ['A new element with an extra proton', 'A negatively charged ion', 'A neutron'], 'Losing a negative electron leaves one more proton than electron, giving a net charge of +1. The unchanged proton count preserves the element’s identity.'),
    q('Calculation', M, 'A nucleus has 6 protons and 8 neutrons. What is its mass number?', '14', ['6', '8', '2'], 'Mass number counts protons plus neutrons: 6 + 8 = 14. It is an integer particle count, not the weighted average atomic mass shown for a natural mixture of isotopes.'),
    q('Calculation', M, 'An ion has 11 protons and 10 electrons. What is its net charge?', '+1', ['−1', '+11', '0'], 'Each proton contributes one positive elementary charge and each electron one negative charge. The difference is 11 − 10 = +1; neutrons do not contribute electric charge.'),
    q('Evidence', M, 'An atom emits light at particular wavelengths. What does this suggest about its electron energies?', 'Allowed energy changes are discrete rather than arbitrary', ['Electrons can only have zero energy', 'The nucleus is made of visible light', 'Every element must have an identical spectrum'], 'An emitted photon carries the energy difference between allowed states. Discrete differences produce spectral lines that can help identify elements.'),
    q('Multi-step', H, 'A neutral atom has atomic number 17 and mass number 35. How many neutrons and electrons does it have?', '18 neutrons and 17 electrons', ['17 neutrons and 18 electrons', '35 neutrons and 17 electrons', '18 neutrons and 35 electrons'], 'Protons = atomic number = 17. Neutrons = 35 − 17 = 18. Neutrality requires electrons to equal protons, so the electron count is 17.'),
    q('Comparison', H, 'A sample contains isotopes of masses approximately 20 and 22 in a 3:1 ratio. What is its approximate mean atomic mass?', '20.5', ['21.0', '42.0', '20.0'], 'A weighted mean accounts for abundance: (3 × 20 + 1 × 22) / 4 = 20.5. An unweighted midpoint of 21 would incorrectly assume equal abundances.'),
  ],
  'science-mathematics--probability': [
    q('Concept', E, 'A fair six-sided die is rolled once. What is the probability of a 6?', '1/6', ['1/2', '5/6', '6'], 'There are six equally likely outcomes, and exactly one is a 6. Probability here is favorable outcomes divided by all equally likely outcomes.'),
    q('Comparison', E, 'What does it mean for two events to be independent?', 'Knowing one occurred does not change the probability of the other', ['They cannot happen together', 'They must have equal probabilities', 'One always causes the other'], 'Independence concerns conditional probability. Mutually exclusive events are different: if one occurs, the other cannot, so nonzero mutually exclusive events are not independent.'),
    q('Misconception', E, 'A fair coin lands heads five times in independent tosses. What is the chance of heads on the next toss?', '1/2', ['0 because tails is due', '1 because the streak must continue', '1/6'], 'The next independent toss does not remember the earlier outcomes. A streak can feel like a force that needs balancing, but the fair coin still has probability 1/2 of heads.'),
    q('Calculation', M, 'What is the probability of heads on both of two independent fair-coin tosses?', '1/4', ['1/2', '1', '3/4'], 'Multiply the independent probabilities: 1/2 × 1/2 = 1/4. The four equally likely ordered outcomes are HH, HT, TH and TT; only HH qualifies.'),
    q('Calculation', M, 'A bag has 3 red and 2 blue balls. One is drawn uniformly at random. What is the probability it is not red?', '2/5', ['3/5', '1/2', '2/3'], 'Not red means blue in this specified bag, so there are 2 qualifying balls out of 5. Equivalently, take the complement: 1 − 3/5 = 2/5.'),
    q('Scenario', M, 'From a standard 52-card deck, you learn a uniformly drawn card is a heart. What is the chance it is an ace?', '1/13', ['1/52', '1/4', '4/13'], 'Conditioning changes the sample space to the 13 hearts. There is one ace of hearts, so the conditional probability is 1/13 rather than the unconditional chance of that exact card.'),
    q('Multi-step', H, 'Two balls are drawn without replacement from 3 red and 2 blue balls. What is the probability both are red?', '3/10', ['9/25', '3/5', '1/10'], 'The first red has probability 3/5. After it is removed, 2 red remain among 4 balls, so the second probability is 2/4. Multiply: (3/5)(2/4) = 3/10.'),
    q('Conditional reasoning', H, 'Of 100 students, 40 take biology and 10 take both biology and music. Among biology students, what fraction take music?', '1/4', ['1/10', '2/5', '1/2'], 'Among biology students narrows the denominator to 40, not all 100. The relevant intersection contains 10 students, so P(music | biology) = 10/40 = 1/4.'),
  ],
  'science-mathematics--statistics': [
    q('Concept', E, 'What is the median of 2, 3 and 100?', '3', ['35', '100', '2'], 'The median is the middle value after ordering the observations. It is less sensitive to a single extreme value than the mean, which here is 35.'),
    q('Comparison', E, 'What does a measure of spread describe?', 'How much observations vary from one another or a center', ['Only the number of categories', 'Proof that one thing causes another', 'The name of the person collecting data'], 'Two data sets can have the same average but different variation. Measures such as range and standard deviation describe aspects of that spread.'),
    q('Scenario', E, 'A poll asks only visitors to a cycling club about commuting by bicycle. What is the main concern when estimating citywide cycling?', 'The sample may overrepresent people who cycle', ['A bigger font would remove the bias', 'Every survey must have exactly ten people', 'Counting responses makes any sample representative'], 'A sampling method can systematically include some groups more than others. Increasing the number of club respondents does not necessarily correct the missing representation.'),
    q('Calculation', M, 'Four quiz scores are 4, 6, 8 and 10. What is their mean?', '7', ['6', '8', '28'], 'The arithmetic mean is total divided by count: (4 + 6 + 8 + 10) / 4 = 28 / 4 = 7. The sum alone is not an average.'),
    q('Evidence', M, 'Ice-cream sales and swimming incidents both rise in summer. What does this correlation alone establish?', 'An association, not proof that ice cream causes the incidents', ['A proven direct causal effect', 'That neither variable can be measured', 'That all seasonal data are false'], 'Warm weather can affect both variables. A shared influence can create correlation, so causal explanations require additional design, evidence and attention to alternative causes.'),
    q('Comparison', M, 'Adding a very large outlier to a small income data set usually affects which center more?', 'The mean more than the median', ['The median more than the mean in every case', 'Neither can ever change', 'Both always become equal to the outlier'], 'The mean incorporates every numerical magnitude, so an extreme value can pull it strongly. The median depends on order and usually changes less; the exact change depends on the data.'),
    q('Multi-step', H, 'Two groups have means 80 and 60, with sizes 10 and 30. What is their combined mean?', '65', ['70', '75', '140'], 'Weight each mean by its group size: (10 × 80 + 30 × 60) / 40 = 2600/40 = 65. Simply averaging the two means ignores their unequal sizes.'),
    q('Inference', H, 'A treatment group improves more than a comparison group, but participants chose their own group. What limits the causal claim?', 'Pre-existing differences may influence both group choice and improvement', ['A comparison group always proves causation', 'A numerical difference cannot be real', 'Self-selection is identical to random assignment'], 'Self-selection can confound the comparison: motivation or baseline health may affect both treatment choice and outcome. A difference can be real without uniquely identifying the treatment’s causal effect.'),
  ],
  'science-mathematics--experiments': [
    q('Concept', E, 'In an experiment on fertilizer and plant height, what is the manipulated independent variable?', 'The fertilizer treatment assigned', ['The measured plant height', 'Every possible environmental condition', 'The researcher’s conclusion'], 'The independent variable is deliberately varied. Plant height is an outcome, while other relevant influences should be controlled or accounted for.'),
    q('Mechanism', E, 'Why include a control group in a treatment experiment?', 'To provide a comparison for estimating what the treatment changes', ['To guarantee the desired result', 'To remove all natural variation', 'To replace measurement'], 'A comparison helps separate changes associated with treatment from changes that might happen anyway. A control improves interpretation but does not automatically eliminate every bias.'),
    q('Evidence', E, 'Why repeat a measurement or experiment?', 'To assess consistency and variation rather than rely on one observation', ['To force every result to match', 'To make an incorrect claim true', 'To avoid reporting methods'], 'Repeated observations help reveal random variation and whether a finding is reproducible. Repetition cannot rescue a systematically biased method unless the design is also improved.'),
    q('Scenario', M, 'Fertilized plants get more light than unfertilized plants. What is the interpretation problem?', 'Light is confounded with fertilizer treatment', ['Plant height cannot be measured', 'More light proves fertilizer has no effect', 'The control group has no variables'], 'Both light and fertilizer differ between groups, so either could contribute to height differences. Comparable lighting helps isolate the effect of fertilizer.'),
    q('Comparison', M, 'What does random assignment of participants primarily help with?', 'Balancing potential confounders between treatment groups on average', ['Guaranteeing a representative sample of the whole population', 'Making every measurement exact', 'Ensuring nobody leaves the study'], 'Random assignment concerns how enrolled participants enter groups; random sampling concerns who enters the study. They address different questions, and chance imbalances can still occur.'),
    q('Misconception', M, 'A well-designed test does not support a hypothesis. What should a scientist do?', 'Reconsider the hypothesis or its predictions in light of the evidence', ['Hide the observations', 'Declare evidence irrelevant', 'Change the recorded results'], 'A test is useful when it can challenge an explanation. Unsupported predictions call for revision or more investigation, not selective removal of inconvenient measurements.'),
    q('Design', H, 'A new teaching method is tested only by comparing this year’s class with last year’s. Which change most strengthens the design?', 'Randomly assign comparable current students to methods and use the same outcome measure', ['Use different exams for each group without calibration', 'Keep only students whose scores improved', 'Report only the highest score'], 'Year-to-year differences may reflect cohort, exam or context changes. A contemporaneous randomized comparison with consistent measurement helps isolate the method while leaving uncertainty to be estimated.'),
    q('Transfer', H, 'Why specify an outcome and analysis before looking at the results?', 'It reduces the risk of choosing a favorable test after seeing the data', ['It guarantees a significant effect', 'It prevents anyone from checking the work', 'It removes all need for exploration'], 'Pre-specification distinguishes planned tests from exploratory findings and reduces selective analysis. Exploratory work remains valuable when it is clearly labeled and tested further.'),
  ],
  'life-sciences--cells': [
    q('Concept', E, 'Which structure is a main site of protein synthesis?', 'A ribosome', ['A cell wall', 'A lipid droplet only', 'An extracellular salt crystal'], 'Ribosomes translate information carried by messenger RNA into amino-acid chains. They exist in both prokaryotic and eukaryotic cells.'),
    q('Comparison', E, 'What distinguishes a typical eukaryotic cell from a prokaryotic cell?', 'A membrane-enclosed nucleus', ['The ability to contain DNA at all', 'The presence of any ribosomes', 'The need for a cell membrane'], 'Both groups have DNA, ribosomes and a plasma membrane. Eukaryotes organize much of their DNA inside a nucleus and have other membrane-bound organelles.'),
    q('Mechanism', E, 'What is the plasma membrane’s central role?', 'To regulate exchange and separate the cell’s interior from its surroundings', ['To make all molecules cross equally', 'To replace every enzyme', 'To eliminate the need for energy'], 'A selectively permeable membrane creates a boundary while permitting controlled transport and signaling. It is an active part of cell organization, not an impermeable bag.'),
    q('Scenario', M, 'A secretory cell produces a protein for export. Which pathway is most directly involved?', 'Ribosomes on rough ER, then processing and sorting through the Golgi', ['Only the cell wall', 'The nucleus directly releasing finished proteins outside', 'DNA leaving the cell to become a protein'], 'Many exported proteins enter the rough endoplasmic reticulum during synthesis. Vesicles carry them through the Golgi for modification and sorting before secretion.'),
    q('Comparison', M, 'Why do many large cells need internal transport rather than relying only on diffusion over their full width?', 'Diffusion becomes too slow over longer distances for many cellular needs', ['Molecules stop moving inside large cells', 'Diffusion requires a nucleus', 'Large cells have no concentration gradients'], 'Random molecular motion is effective over short distances, but diffusion time grows strongly with distance. Cells use structures and energy-dependent transport to move cargo efficiently.'),
    q('Misconception', M, 'Which statement about plant cells is correct?', 'They use mitochondria as well as, in photosynthetic tissues, chloroplasts', ['They never carry out cellular respiration', 'Every plant cell must contain chloroplasts', 'Their cell wall replaces the plasma membrane'], 'Plants need ATP for many activities and perform cellular respiration. Chloroplasts capture light energy in photosynthetic cells; roots commonly lack them, and a plasma membrane remains inside the wall.'),
    q('Scaling', H, 'For a cube-shaped cell, doubling each side length changes surface area and volume by which factors?', 'Surface area ×4 and volume ×8', ['Surface area ×2 and volume ×2', 'Surface area ×8 and volume ×4', 'Both ×4'], 'Surface area scales with length squared and volume with length cubed. Doubling length reduces the surface-area-to-volume ratio, affecting exchange relative to internal demand.'),
    q('Inference', H, 'A cell’s ATP production falls sharply. Which process would be directly limited most clearly?', 'An ATP-driven membrane pump moving ions against a gradient', ['All molecular diffusion stopping immediately', 'Every molecule losing its mass', 'The disappearance of the lipid bilayer'], 'ATP-driven pumps require an energy input for uphill transport. Passive diffusion is powered by molecular motion and gradients, although gradients can later change when pumps stop.'),
  ],
  'life-sciences--membranes': [
    q('Concept', E, 'What is diffusion’s net direction when a concentration gradient exists?', 'From higher to lower concentration for that substance', ['Always from lower to higher concentration', 'Always toward the nucleus', 'Only in the direction of gravity'], 'Particles move randomly in both directions, but a gradient produces net movement from higher to lower concentration. At equilibrium particles still move; the net directional flow is zero.'),
    q('Comparison', E, 'What specifically moves in osmosis?', 'Water through a selectively permeable membrane', ['Only DNA through a nucleus', 'Only ions using ATP', 'Every solute at the same speed'], 'Osmosis is water movement across a selectively permeable membrane. Differences in water potential, including solute concentration and pressure, determine its net direction.'),
    q('Mechanism', E, 'What makes active transport different from passive transport?', 'It uses energy to move substances against an electrochemical gradient', ['It never uses membrane proteins', 'It happens only outside cells', 'It requires every solute to be water'], 'Moving uphill against an electrochemical gradient needs an energy source, directly or through coupling to another gradient. Passive transport moves downhill without that external energy input.'),
    q('Scenario', M, 'A red blood cell is placed in a strongly hypotonic solution. What tends to happen?', 'Water enters and the cell may swell and burst', ['Water always leaves and the cell shrinks', 'The cell immediately grows a cell wall', 'Its DNA becomes salt'], 'The external solution has lower effective nonpenetrating solute concentration. Water tends to enter; unlike plant cells, red blood cells have no rigid wall to resist excessive swelling.'),
    q('Comparison', M, 'A channel lets ions move down their electrochemical gradient. What process is this?', 'Facilitated diffusion', ['ATP-driven pumping by definition', 'DNA replication', 'Osmosis of ions'], 'A membrane protein can facilitate passive movement. Protein involvement alone does not make transport active; the direction relative to the gradient and energy coupling matter.'),
    q('Misconception', M, 'At diffusion equilibrium, what are individual molecules doing?', 'Still moving randomly, with no net directional flux', ['All standing still', 'Moving only in one direction', 'Turning into membrane proteins'], 'Equilibrium is dynamic: movement continues in both directions. Equal average flows produce no net change in distribution, rather than a complete halt of microscopic motion.'),
    q('Multi-step', H, 'A membrane passes water but not a dissolved sugar. At equal initial pressures, side A has more sugar than side B. What is the initial net water movement?', 'From B toward A', ['From A toward B', 'No movement is possible because sugar is blocked', 'Sugar must turn into water first'], 'At equal pressure, the side with more nonpenetrating solute has lower water potential. Water initially moves toward A; later a pressure difference can counter the osmotic tendency.'),
    q('Transfer', H, 'Why can a sodium gradient drive glucose uptake against glucose’s own gradient?', 'Coupled transport uses sodium’s downhill movement as an energy source', ['Glucose must be moving downhill too', 'The transporter creates energy from nothing', 'No energy is involved because ATP is not split by that transporter'], 'Secondary active transport couples an unfavorable move to a favorable one. ATP-powered pumps often maintain the sodium gradient elsewhere, so the system still depends on an energy input.'),
  ],
  'life-sciences--enzymes': [
    q('Concept', E, 'How does an enzyme speed a reaction?', 'By lowering the activation-energy barrier', ['By making energy conservation stop applying', 'By permanently becoming the product', 'By changing every reaction into combustion'], 'An enzyme provides a pathway with a lower activation barrier. It speeds the approach to equilibrium but does not change the reaction’s overall free-energy difference.'),
    q('Mechanism', E, 'Why is an enzyme usually selective about its substrates?', 'Its active site has a compatible shape and chemical environment', ['Every enzyme binds every molecule equally', 'Substrates choose a site by intention', 'An enzyme contains the name of its substrate'], 'Binding depends on molecular fit and chemical interactions, and the site can adjust during binding. Specificity is a property of structure and chemistry, not a conscious choice.'),
    q('Comparison', E, 'What happens to an enzyme after a normal catalytic cycle?', 'It can catalyze another cycle', ['It is necessarily consumed as a reactant', 'It always becomes DNA', 'It can never bind another substrate'], 'Catalysts participate in reaction steps and are regenerated overall. Enzymes can eventually be damaged or degraded, but one normal catalytic cycle does not consume them.'),
    q('Scenario', M, 'An enzyme loses activity after excessive heating. What is a plausible reason?', 'Its folded structure and active site have been disrupted', ['Its atoms have all disappeared', 'Heat always makes every enzyme faster without limit', 'Its substrate automatically became a different element'], 'Temperature can initially increase reaction rates, but excessive heat can denature a protein. A disrupted active site may no longer bind or stabilize the needed reaction state effectively.'),
    q('Comparison', M, 'A competitive inhibitor occupies the active site. What is it competing with?', 'The substrate for binding at that site', ['All protons in the nucleus', 'Light for access to the eye', 'The cell wall for its location'], 'A competitive inhibitor reduces substrate binding by occupying the active site. In simple reversible models, increasing substrate concentration can lessen its effect.'),
    q('Evidence', M, 'Adding more substrate stops increasing the rate while enzyme amount is fixed. What is a likely explanation?', 'The enzymes are near saturation', ['The reaction has no enzyme', 'All substrates are always inhibitors', 'The enzyme must create extra active sites instantly'], 'At high substrate concentration, active sites spend most of their time occupied. The available enzymes’ turnover limits the rate; adding enzyme can increase that capacity.'),
    q('Transfer', H, 'Why does adding a catalyst not change the equilibrium ratio of products to reactants?', 'It accelerates forward and reverse pathways without changing their free-energy difference', ['It lowers only the mass of the products', 'It changes which atoms exist', 'Equilibrium means reactions never occur'], 'Equilibrium composition is set by thermodynamics under the specified conditions. Catalysis changes kinetics, allowing the same equilibrium to be reached faster rather than selecting a new one.'),
    q('Design', H, 'To test pH’s effect on an enzyme fairly, which design is strongest?', 'Vary pH while keeping enzyme amount, temperature and substrate conditions comparable', ['Change pH and temperature together without recording them', 'Use a different enzyme for every pH', 'Measure only the tube that looks most active'], 'Other changes could explain the rate differences. Controlling relevant conditions and using repeated measurements makes the specific effect of pH more interpretable.'),
  ],
  'life-sciences--genetics': [
    q('Concept', E, 'What is an allele?', 'A version of a gene at a particular locus', ['An entire species', 'A protein-making organelle', 'A synonym for a chromosome pair'], 'Alleles are alternative versions at a gene’s location. An individual can carry two alleles at an autosomal locus, while a population can contain many versions.'),
    q('Comparison', E, 'What is the difference between genotype and phenotype?', 'Genotype concerns genetic makeup; phenotype concerns observable characteristics', ['They always mean the same thing', 'Phenotype is only a chromosome number', 'Genotype is a person’s learned opinion'], 'Phenotypes result from genetic and environmental influences and their interactions. A genotype describes inherited variants, not a guarantee of every observable outcome.'),
    q('Mechanism', E, 'What does transcription produce from a DNA template?', 'RNA', ['A complete organism immediately', 'A lipid membrane', 'An extra proton'], 'During transcription, RNA polymerase builds RNA using a DNA template. Translation is a different process in which ribosomes use messenger RNA to build a polypeptide.'),
    q('Calculation', M, 'In a simple Mendelian model, two heterozygous parents Aa × Aa have what probability of an aa offspring?', '1/4', ['1/2', '3/4', '1'], 'Each parent supplies a with probability 1/2 in this model. Multiplying gives 1/4 for aa; the other combinations are AA and the two ways to obtain Aa.'),
    q('Misconception', M, 'Does a dominant allele have to be more common in a population?', 'No; dominance describes a heterozygote’s phenotype, not population frequency', ['Yes, by definition it must exceed 50%', 'Yes, because it forces all other alleles to disappear', 'No allele can be rare'], 'Dominant and recessive describe expression in a specified genetic model. Frequency depends on inheritance, selection, drift and other population processes, not the word dominant.'),
    q('Scenario', M, 'A trait varies with both inherited variants and nutrition. What does this illustrate?', 'Genetic and environmental contributions to phenotype', ['That DNA cannot affect traits', 'That nutrition changes the element of every atom', 'That every trait follows one dominant allele'], 'Many traits are influenced by multiple genes and environmental conditions. Explaining a phenotype often requires both rather than treating nature and nurture as mutually exclusive.'),
    q('Multi-step', H, 'In the simple model Aa × aa, with A completely dominant, what fraction of offspring is expected to show the recessive phenotype?', '1/2', ['1/4', '3/4', '0'], 'The heterozygous parent supplies A or a with equal probability; the aa parent supplies a. Expected genotypes are half Aa and half aa, so half show the recessive phenotype.'),
    q('Transfer', H, 'Why does a 1/4 inheritance probability not guarantee exactly one affected child in a family of four?', 'Probabilities describe possible outcomes; independent births can produce different counts', ['The probability changes to zero after one birth', 'Four children always divide exactly into all possible genotypes', 'Mendelian probabilities apply only to very large animals'], 'The probability applies to each birth under the model. A small family can have zero, one or several affected children; expected proportions are not a schedule that every family must follow.'),
  ],
  'earth-space--orbits': [
    q('Concept', E, 'What keeps Earth following a curved orbit around the Sun?', 'The Sun’s gravitational attraction', ['A solid track through space', 'The absence of all forces', 'Earth’s atmosphere pushing against the Sun'], 'Earth’s forward motion and the Sun’s gravitational pull combine into an orbit. Gravity continuously changes the direction of velocity instead of needing a physical track.'),
    q('Mechanism', E, 'What is the main cause of Earth’s seasons?', 'The tilt of its rotation axis as it orbits the Sun', ['Earth being much closer to the Sun in every local summer', 'The Moon blocking sunlight all winter', 'The Sun switching its fusion off each winter'], 'Axial tilt changes sunlight angle and day length in each hemisphere during the year. The hemispheres have opposite seasons, which a shared change in Earth–Sun distance cannot explain.'),
    q('Misconception', E, 'Why do astronauts in an orbiting spacecraft feel weightless?', 'They and the spacecraft are falling together around Earth', ['Earth’s gravity is exactly zero there', 'Their mass disappears', 'A spacecraft removes all gravitational fields'], 'Gravity remains substantial in low Earth orbit. Weightlessness occurs because the spacecraft and its occupants share free fall, so there is little supporting force pressing them against a floor.'),
    q('Comparison', M, 'For circular orbits around the same central mass, which orbit has a longer period?', 'The larger-radius orbit', ['The smaller-radius orbit', 'All radii have identical periods', 'An orbit’s period depends only on the spacecraft’s paint'], 'For the same central mass, orbital period increases with orbit size according to Kepler’s third law. A farther circular orbit also has a lower orbital speed.'),
    q('Scenario', M, 'The Northern Hemisphere tilts toward the Sun. What tends to happen there?', 'Longer days and more direct sunlight', ['Shorter days everywhere north of the equator', 'The Southern Hemisphere must have the same summer', 'Earth’s rotation stops'], 'The tilt gives much of the Northern Hemisphere longer illumination and a higher solar angle. The Southern Hemisphere simultaneously tilts away, giving an opposing seasonal pattern.'),
    q('Comparison', M, 'Why does the Moon show phases during its orbit?', 'We see different portions of its sunlit half', ['Earth’s shadow causes every phase', 'The Moon produces changing amounts of its own visible light', 'The Sun circles the Moon once each week'], 'Half the Moon is illuminated by the Sun, except during eclipses. Its changing position relative to Earth and the Sun changes how much of that lit half we can see.'),
    q('Scaling', H, 'At twice the distance from the same point-like mass, how does gravitational force on the same test mass change?', 'It falls to one quarter', ['It halves', 'It doubles', 'It becomes zero'], 'Newtonian gravitational force scales as 1/r². Replacing r with 2r divides the force by four, under the stated approximation and with the masses unchanged.'),
    q('Transfer', H, 'For a satellite in a circular orbit, why does gravity change direction of motion without increasing its speed?', 'The gravitational force is perpendicular to its instantaneous velocity', ['Gravity does not act on moving objects', 'The satellite has no kinetic energy', 'Any force must always increase speed'], 'A perpendicular force changes velocity’s direction but does no instantaneous work. Circular orbital speed stays constant even though velocity continually changes; elliptical orbits behave differently.'),
  ],
  'technology--ai-learning': [
    q('Concept', E, 'What is the distinction between training and inference in a machine-learning model?', 'Training adjusts model parameters; inference uses the learned model on inputs', ['Inference always rewrites the training data', 'Training means displaying a prediction', 'They must use identical data and code paths'], 'Training optimizes parameters using examples and a learning objective. Inference applies the resulting model; ordinary inference does not necessarily update its weights.'),
    q('Mechanism', E, 'Why hold out test data from training?', 'To estimate performance on examples the model did not learn from', ['To make the model memorize the test answers', 'To guarantee perfect deployment performance', 'To remove every unusual example'], 'An untouched test set helps estimate generalization. Repeatedly tuning decisions against it leaks information into development, weakening its value as an independent final check.'),
    q('Comparison', E, 'What is overfitting?', 'Learning training-specific patterns that do not generalize well', ['Always having too few parameters', 'A model predicting at any speed', 'Using only new unseen data'], 'A model can fit noise or incidental details in training examples. High training performance with substantially weaker held-out performance is one warning sign.'),
    q('Scenario', M, 'A model predicts tomorrow’s event using a field recorded only after the event. What is the problem?', 'Data leakage from information unavailable at prediction time', ['A guaranteed causal discovery', 'A necessary feature of every model', 'An improvement that cannot affect evaluation'], 'The feature gives the model information it would not have in real use. Evaluation may look excellent while the deployed prediction is impossible or much weaker.'),
    q('Comparison', M, 'Why might accuracy alone mislead when 99% of examples belong to one class?', 'Always choosing the majority class can score 99% while missing every minority example', ['Accuracy becomes mathematically impossible to calculate', 'Every model must then be perfect', 'Class proportions have no effect on evaluation'], 'A high overall accuracy can hide failure on an important rare class. Class-specific recall, precision and the costs of errors can make evaluation more informative.'),
    q('Evidence', M, 'A model performs well on one test set. What is a sensible next check before broader use?', 'Evaluate on data that reflects the intended users and changing conditions', ['Assume every future setting is identical', 'Delete all incorrectly predicted examples', 'Stop monitoring permanently'], 'Generalization depends on the relationship between evaluation data and deployment conditions. Distribution changes and underrepresented groups can expose errors that one test set missed.'),
    q('Design', H, 'For predicting a time series, why can a random row split produce an overly optimistic result?', 'Related future information can leak into training; a chronological evaluation better matches forecasting', ['Time has no relation to forecasting', 'Chronological splits guarantee no uncertainty', 'Random splits always reduce the training size to zero'], 'Neighboring observations may share patterns, and future-derived features can leak backward. A time-aware split and features available at the forecast date give a more realistic test.'),
    q('Multi-step', H, 'A classifier flags 100 items: 20 truly belong to the target class. There are 50 target items in total. What are precision and recall?', 'Precision 20%; recall 40%', ['Precision 40%; recall 20%', 'Both 20%', 'Both 50%'], 'Precision asks how many flagged items are correct: 20/100 = 20%. Recall asks how many actual target items were found: 20/50 = 40%. They answer different questions.'),
  ],
};

